tool_schemas.implementation:
def Optional_Settings(action, account_id=None, connection_id=None, session_id=None, api_key_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, connections_filter=None, accounts_filter=None, api_keys_filter=None, connection=None, sign_in=None, sign_out=None, set_default=None, create_api_key=None, revoke_api_key=None, update_account=None, **_extra):
    import json, os, datetime, re, time, secrets, base64, urllib.parse, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0073000" if __import__("os").path.isdir("./environment_mix/0073000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    endpoint = "Optional Settings"

    # ---------- request logging + rate/quota ----------
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _find_log_file():
        # prefer existing; else create request_logs.json
        for fn in ("request_logs.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _load_logs(fn):
        logs = _load(fn)
        return logs if isinstance(logs, list) else []

    def _enforce_limits(logs, limit_key):
        # Simple service dynamics: 120/minute and 10k/day per limit_key
        window_sec = 60
        rate_limit = 120
        daily_quota = 10000

        win_start = now - datetime.timedelta(seconds=window_sec)
        day_start = datetime.datetime(now.year, now.month, now.day)

        rate_count = 0
        day_count = 0
        for r in logs:
            if r.get("limit_key") != limit_key:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                rate_count += 1
            if ts >= day_start:
                day_count += 1
        if rate_count >= rate_limit:
            return _err("RATE_LIMIT", "Too many requests; slow down.", limit=rate_limit, window_seconds=window_sec)
        if day_count >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota=daily_quota, period="day")
        return None

    def _log_and_return(fn, logs, resp, status, credential_type=None, credential_id=None, acct=None, meta=None):
        logs.append({
            "id": _gen_id("dbmcp_req"),
            "endpoint": endpoint,
            "timestamp": now_iso,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_type": credential_type,
            "credential_id": credential_id,
            "account_id": acct,
            "limit_key": acct or credential_id or "anonymous",
            "meta": meta or {}
        })
        _save(fn, logs)
        return resp

    # ---------- validation ----------
    allowed_actions = {
        "sign_in", "sign_out", "get_session",
        "list_connections", "get_connection", "create_connection", "update_connection",
        "delete_connection", "set_default_connection", "validate_connection",
        "list_api_keys", "create_api_key", "revoke_api_key",
        "list_accounts", "get_account", "update_account_status"
    }
    if not isinstance(action, str) or action not in allowed_actions:
        fn = _find_log_file()
        logs = _load_logs(fn)
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid action", allowed=sorted(allowed_actions)), "VALIDATION_ERROR")

    def _match(pat, s):
        return isinstance(s, str) and re.match(pat, s) is not None

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _is_obj(x):
        return isinstance(x, dict)

    def _is_bool(x):
        return isinstance(x, bool)

    def _is_url(x):
        if not isinstance(x, str) or not x:
            return False
        try:
            u = urllib.parse.urlparse(x)
            return u.scheme in ("http", "https") and bool(u.netloc)
        except Exception:
            return False

    def _iso_or_none(dt):
        if dt is None:
            return None
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _require_id(name, value, pat):
        if value is None:
            return None
        if not _match(pat, value):
            return _err("VALIDATION_ERROR", f"Invalid {name}", field=name)
        return None

    # validate common ids if provided (but don't require them unless action needs them)
    for nm, val, pat in (
        ("account_id", account_id, r"^dbmcp_acct_[0-9A-Z]{18,}$"),
        ("connection_id", connection_id, r"^dbmcp_conn_[0-9A-Z]{18,}$"),
        ("session_id", session_id, r"^dbmcp_sess_[0-9A-Z]{18,}$"),
        ("api_key_id", api_key_id, r"^dbmcp_key_[0-9A-Z]{18,}$"),
    ):
        e = _require_id(nm, val, pat)
        if e:
            fn = _find_log_file()
            logs = _load_logs(fn)
            lim_err = _enforce_limits(logs, account_id or "anonymous")
            if lim_err:
                return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
            return _log_and_return(fn, logs, e, "VALIDATION_ERROR")

    if limit is not None:
        if not _is_int(limit) or limit < 1 or limit > 200:
            fn = _find_log_file()
            logs = _load_logs(fn)
            lim_err = _enforce_limits(logs, account_id or "anonymous")
            if lim_err:
                return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
            return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit"), "VALIDATION_ERROR")
    if sort_order is not None and sort_order not in ("asc", "desc"):
        fn = _find_log_file()
        logs = _load_logs(fn)
        lim_err = _enforce_limits(logs, account_id or "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order"), "VALIDATION_ERROR")

    # ---------- load data ----------
    accounts = _load("accounts.json")
    conns = _load("databricks_connections.json")
    sessions = _load("auth_sessions.json")
    keys = _load("api_keys.json")

    if not isinstance(accounts, list): accounts = []
    if not isinstance(conns, list): conns = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(keys, list): keys = []

    # auto-expire any active sessions past expires_at (observable mutation)
    sessions_changed = False
    for s in sessions:
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now and s.get("revoked_at") is None:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                sessions_changed = True
    if sessions_changed:
        _save("auth_sessions.json", sessions)

    # ---------- ambient auth/context resolution ----------
    # This endpoint has no explicit credential; resolve a workable context from store.
    def _resolve_context(prefer_account_id=None):
        # choose an active account; for member operations, any active account is acceptable
        cand_accounts = []
        if prefer_account_id:
            for a in accounts:
                if a.get("id") == prefer_account_id:
                    cand_accounts.append(a)
                    break
        if not cand_accounts:
            cand_accounts = [a for a in accounts if a.get("status") == "active"]
        # for operations that need an active connection, pick one under same account
        for a in cand_accounts:
            if a.get("status") != "active":
                continue
            acct_id = a.get("id")
            # pick default active connection if any, else any active
            acct_conns = [c for c in conns if c.get("account_id") == acct_id and c.get("status") == "active"]
            default_conn = None
            for c in acct_conns:
                if c.get("is_default") is True:
                    default_conn = c
                    break
            return a, (default_conn or (acct_conns[0] if acct_conns else None))
        return None, None

    ctx_account, ctx_conn = _resolve_context(account_id)
    # Some actions are purely list operations and can operate even without a connection, but must have an account context.
    if ctx_account is None:
        fn = _find_log_file()
        logs = _load_logs(fn)
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "No active account context available."), "UNAUTHORIZED")

    # Rate/quota key is the resolved account
    fn = _find_log_file()
    logs = _load_logs(fn)
    lim_err = _enforce_limits(logs, ctx_account.get("id"))
    if lim_err:
        return _log_and_return(fn, logs, lim_err, "RATE_LIMIT", acct=ctx_account.get("id"))

    # ---------- helpers: filtering/sorting/paging ----------
    def _sort_rows(rows, by, order):
        if not by:
            return rows
        reverse = (order == "desc")
        def keyfn(r):
            v = r.get(by)
            # try parse datetime for known dt fields
            if by in ("created_at", "updated_at", "last_login_at", "last_used_at", "expires_at", "last_validated_at", "issued_at"):
                dt = _parse_dt(v)
                return dt or datetime.datetime.min
            return "" if v is None else v
        return sorted(rows, key=keyfn, reverse=reverse)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        s = cur.strip()
        # support both numeric cursor and base64 cursor
        if s.isdigit():
            return int(s)
        try:
            pad = "=" * ((4 - len(s) % 4) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii")).decode("utf-8")
            return int(raw)
        except Exception:
            return None

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("ascii").rstrip("=")

    def _page(rows):
        lim = limit if limit is not None else 50
        start = _decode_cursor(cursor)
        if start is None:
            return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        total = len(rows)
        end = min(start + lim, total)
        page_rows = rows[start:end]
        has_more = end < total
        next_cur = _encode_cursor(end) if has_more else None
        return {
            "data": page_rows,
            "total": total,
            "limit": lim,
            "cursor": cursor,
            "next_cursor": next_cur,
            "has_more": has_more
        }, None

    # ---------- business rule helpers ----------
    def _account_by_id(aid):
        for a in accounts:
            if a.get("id") == aid:
                return a
        return None

    def _conn_by_id(cid):
        for c in conns:
            if c.get("id") == cid:
                return c
        return None

    def _sess_by_id(sid):
        for s in sessions:
            if s.get("id") == sid:
                return s
        return None

    def _key_by_id(kid):
        for k in keys:
            if k.get("id") == kid:
                return k
        return None

    def _deny_if_account_inactive_for_mutations(acct):
        if acct is None:
            return _err("NOT_FOUND", "Account not found.")
        if acct.get("status") in ("suspended", "deleted"):
            return _err("UNAUTHORIZED", "Account is not permitted to perform this operation while suspended/deleted.", rule="suspended/deleted cannot mutate")
        return None

    # ---------- ACTIONS ----------
    try:
        # --- sessions ---
        if action == "sign_in":
            # Accept either sign_in object or top-level args (audit shows callers pass top-level too)
            payload = sign_in if _is_obj(sign_in) else {}
            aid = payload.get("account_id") or account_id or ctx_account.get("id")
            cid = payload.get("connection_id") or connection_id or (ctx_conn.get("id") if ctx_conn else None)
            cm = payload.get("client_metadata")
            expires_at_s = payload.get("expires_at")

            if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", aid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "account_id is required for sign_in", field="account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection_id is required for sign_in", field="connection_id"), "VALIDATION_ERROR", acct=aid)

            acct = _account_by_id(aid)
            e = _deny_if_account_inactive_for_mutations(acct)
            if e:
                return _log_and_return(fn, logs, e, "UNAUTHORIZED", acct=aid)

            conn = _conn_by_id(cid)
            if conn is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=cid), "NOT_FOUND", acct=aid)
            if conn.get("account_id") != aid:
                return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Connection does not belong to account."), "UNAUTHORIZED", acct=aid)
            if conn.get("status") != "active":
                return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Cannot create session for non-active connection.", rule="new sessions require active connection"), "INVALID_TRANSITION", acct=aid)

            issued_at = now
            if expires_at_s is not None:
                exp = _parse_dt(expires_at_s)
                if exp is None:
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "expires_at must be RFC3339 datetime", field="expires_at"), "VALIDATION_ERROR", acct=aid)
                expires_at = exp
            else:
                expires_at = issued_at + datetime.timedelta(hours=24)

            if expires_at <= issued_at:
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "expires_at must be after issued_at", field="expires_at"), "VALIDATION_ERROR", acct=aid)

            # token is not returned as plaintext in store; but API returns it once to client.
            session_token_plain = "dbmcp_sess_tok_" + secrets.token_urlsafe(24)
            # Store client-presented value directly in session_token_hash column per business rules for this sandbox backend
            sess = {
                "id": _gen_id("dbmcp_sess"),
                "account_id": aid,
                "connection_id": cid,
                "session_token_hash": session_token_plain,  # matched by plaintext in this datastore (see rules)
                "issued_at": _iso_or_none(issued_at),
                "expires_at": _iso_or_none(expires_at),
                "revoked_at": None,
                "client_metadata": cm if isinstance(cm, dict) else (cm if cm is None else {"value": cm}),
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            sessions.append(sess)
            _save("auth_sessions.json", sessions)

            # update last_login_at for account
            if acct is not None:
                acct["last_login_at"] = now_iso
                acct["updated_at"] = now_iso
                _save("accounts.json", accounts)

            resp = {
                "session": sess,
                "session_token": session_token_plain
            }
            return _log_and_return(fn, logs, resp, "OK", acct=aid, meta={"action": "sign_in"})

        if action == "sign_out":
            payload = sign_out if _is_obj(sign_out) else {}
            sid = payload.get("session_id") or session_id
            if not _match(r"^dbmcp_sess_[0-9A-Z]{18,}$", sid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "session_id is required for sign_out", field="session_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))

            sess = _sess_by_id(sid)
            if sess is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Session not found.", session_id=sid), "NOT_FOUND", acct=ctx_account.get("id"))

            if sess.get("status") == "revoked":
                # idempotent revoke
                return _log_and_return(fn, logs, {"session": sess}, "OK", acct=sess.get("account_id"), meta={"idempotent": True})

            if sess.get("status") not in ("active", "expired"):
                return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Session cannot be revoked from current status.", from_status=sess.get("status"), to_status="revoked"), "INVALID_TRANSITION", acct=sess.get("account_id"))

            sess["status"] = "revoked"
            sess["revoked_at"] = now_iso
            sess["updated_at"] = now_iso
            _save("auth_sessions.json", sessions)
            return _log_and_return(fn, logs, {"session": sess}, "OK", acct=sess.get("account_id"))

        if action == "get_session":
            sid = session_id
            if not _match(r"^dbmcp_sess_[0-9A-Z]{18,}$", sid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "session_id is required", field="session_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            sess = _sess_by_id(sid)
            if sess is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Session not found.", session_id=sid), "NOT_FOUND", acct=ctx_account.get("id"))
            return _log_and_return(fn, logs, {"session": sess}, "OK", acct=sess.get("account_id"))

        # --- connections ---
        if action == "list_connections":
            filt = connections_filter if _is_obj(connections_filter) else {}
            rows = conns[:]
            # default filter by resolved account if none specified
            acct_filter = filt.get("account_id") or account_id or ctx_account.get("id")
            if acct_filter is not None:
                if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", acct_filter):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid connections_filter.account_id", field="connections_filter.account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
                rows = [r for r in rows if r.get("account_id") == acct_filter]
            if "status" in filt and filt["status"] is not None:
                rows = [r for r in rows if r.get("status") == filt["status"]]
            if "cloud" in filt and filt["cloud"] is not None:
                rows = [r for r in rows if r.get("cloud") == filt["cloud"]]
            if "auth_type" in filt and filt["auth_type"] is not None:
                rows = [r for r in rows if r.get("auth_type") == filt["auth_type"]]
            if "is_default" in filt and filt["is_default"] is not None:
                if not _is_bool(filt["is_default"]):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connections_filter.is_default must be boolean", field="connections_filter.is_default"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
                rows = [r for r in rows if bool(r.get("is_default")) == filt["is_default"]]
            if "workspace_id" in filt and filt["workspace_id"] is not None:
                rows = [r for r in rows if r.get("workspace_id") == filt["workspace_id"]]
            if "databricks_host" in filt and filt["databricks_host"] is not None:
                rows = [r for r in rows if r.get("databricks_host") == filt["databricks_host"]]

            rows = _sort_rows(rows, sort_by or "created_at", sort_order or "desc")
            page, pe = _page(rows)
            if pe:
                return _log_and_return(fn, logs, pe, "VALIDATION_ERROR", acct=ctx_account.get("id"))
            return _log_and_return(fn, logs, page, "OK", acct=acct_filter)

        if action == "get_connection":
            cid = connection_id
            if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection_id is required", field="connection_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            conn = _conn_by_id(cid)
            if conn is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=cid), "NOT_FOUND", acct=ctx_account.get("id"))
            return _log_and_return(fn, logs, {"connection": conn}, "OK", acct=conn.get("account_id"))

        if action in ("create_connection", "update_connection"):
            if not _is_obj(connection):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection object is required", field="connection"), "VALIDATION_ERROR", acct=ctx_account.get("id"))

            if action == "create_connection":
                required = ("account_id", "name", "databricks_host", "cloud", "auth_type", "is_default", "status")
                missing = [k for k in required if k not in connection]
                if missing:
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Missing required connection fields", missing=missing), "VALIDATION_ERROR", acct=ctx_account.get("id"))

                aid = connection.get("account_id")
                if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", aid or ""):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid connection.account_id", field="connection.account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
                acct = _account_by_id(aid)
                e = _deny_if_account_inactive_for_mutations(acct)
                if e:
                    return _log_and_return(fn, logs, e, "UNAUTHORIZED", acct=aid)

                nm = connection.get("name")
                if not isinstance(nm, str) or not nm.strip():
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection.name must be a non-empty string", field="connection.name"), "VALIDATION_ERROR", acct=aid)

                # unique(account_id, name)
                for c in conns:
                    if c.get("account_id") == aid and c.get("name") == nm:
                        return _log_and_return(fn, logs, _err("CONFLICT", "A connection with this name already exists for the account.", constraint="unique(account_id,name)"), "CONFLICT", acct=aid)

                host = connection.get("databricks_host")
                if not _is_url(host):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection.databricks_host must be a valid URL", field="connection.databricks_host"), "VALIDATION_ERROR", acct=aid)

                cloud = connection.get("cloud")
                if cloud not in ("aws", "azure", "gcp", "unknown"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid connection.cloud", field="connection.cloud"), "VALIDATION_ERROR", acct=aid)

                auth_type = connection.get("auth_type")
                if auth_type not in ("pat", "oauth", "azure_sp", "gcp_sa", "instance_profile", "none"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid connection.auth_type", field="connection.auth_type"), "VALIDATION_ERROR", acct=aid)

                st = connection.get("status")
                if st not in ("active", "disabled", "deleted"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid connection.status", field="connection.status"), "VALIDATION_ERROR", acct=aid)

                is_def = connection.get("is_default")
                if not _is_bool(is_def):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection.is_default must be boolean", field="connection.is_default"), "VALIDATION_ERROR", acct=aid)
                if is_def and st != "active":
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "is_default implies status='active'", constraint="is_default implies status='active'"), "VALIDATION_ERROR", acct=aid)

                # secret_ref only; never accept plaintext secret fields (best-effort check)
                if any(k in connection for k in ("pat", "token", "refresh_token", "client_secret", "secret")):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Secret material must not be provided in plaintext; use secret_ref.", rule="no plaintext secrets"), "VALIDATION_ERROR", acct=aid)

                row = {
                    "id": _gen_id("dbmcp_conn"),
                    "account_id": aid,
                    "name": nm,
                    "databricks_host": host,
                    "cloud": cloud,
                    "workspace_id": connection.get("workspace_id"),
                    "auth_type": auth_type,
                    "secret_ref": connection.get("secret_ref"),
                    "is_default": bool(is_def),
                    "status": st,
                    "last_validated_at": None,
                    "created_at": now_iso,
                    "updated_at": now_iso
                }

                # enforce single default active: unset other defaults in same account in same transaction
                if row["is_default"] and row["status"] == "active":
                    for c in conns:
                        if c.get("account_id") == aid and c.get("status") == "active" and c.get("is_default") is True:
                            c["is_default"] = False
                            c["updated_at"] = now_iso

                conns.append(row)
                _save("databricks_connections.json", conns)
                return _log_and_return(fn, logs, {"connection": row}, "OK", acct=aid)

            # update_connection
            cid = connection_id
            if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection_id is required", field="connection_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            row = _conn_by_id(cid)
            if row is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=cid), "NOT_FOUND", acct=ctx_account.get("id"))

            acct = _account_by_id(row.get("account_id"))
            e = _deny_if_account_inactive_for_mutations(acct)
            if e:
                return _log_and_return(fn, logs, e, "UNAUTHORIZED", acct=row.get("account_id"))

            # lifecycle transitions enforced
            if "status" in connection and connection["status"] is not None:
                new_st = connection["status"]
                if new_st not in ("active", "disabled", "deleted"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid status", field="connection.status"), "VALIDATION_ERROR", acct=row.get("account_id"))
                old_st = row.get("status")
                transitions = {"active": {"disabled", "deleted"}, "disabled": {"active", "deleted"}, "deleted": set()}
                if new_st != old_st and new_st not in transitions.get(old_st, set()):
                    return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Illegal connection status transition.", from_status=old_st, to_status=new_st), "INVALID_TRANSITION", acct=row.get("account_id"))
                if connection.get("is_default") is True and new_st != "active":
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "is_default implies status='active'", constraint="is_default implies status='active'"), "VALIDATION_ERROR", acct=row.get("account_id"))
                row["status"] = new_st

            if "databricks_host" in connection and connection["databricks_host"] is not None:
                if not _is_url(connection["databricks_host"]):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "databricks_host must be a valid URL", field="connection.databricks_host"), "VALIDATION_ERROR", acct=row.get("account_id"))
                row["databricks_host"] = connection["databricks_host"]

            if "name" in connection and connection["name"] is not None:
                nm = connection["name"]
                if not isinstance(nm, str) or not nm.strip():
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "name must be a non-empty string", field="connection.name"), "VALIDATION_ERROR", acct=row.get("account_id"))
                # unique(account_id, name)
                for c in conns:
                    if c.get("id") != row.get("id") and c.get("account_id") == row.get("account_id") and c.get("name") == nm:
                        return _log_and_return(fn, logs, _err("CONFLICT", "A connection with this name already exists for the account.", constraint="unique(account_id,name)"), "CONFLICT", acct=row.get("account_id"))
                row["name"] = nm

            if "cloud" in connection and connection["cloud"] is not None:
                if connection["cloud"] not in ("aws", "azure", "gcp", "unknown"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid cloud", field="connection.cloud"), "VALIDATION_ERROR", acct=row.get("account_id"))
                row["cloud"] = connection["cloud"]

            if "auth_type" in connection and connection["auth_type"] is not None:
                if connection["auth_type"] not in ("pat", "oauth", "azure_sp", "gcp_sa", "instance_profile", "none"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid auth_type", field="connection.auth_type"), "VALIDATION_ERROR", acct=row.get("account_id"))
                row["auth_type"] = connection["auth_type"]

            if "workspace_id" in connection:
                row["workspace_id"] = connection.get("workspace_id")

            if "secret_ref" in connection:
                row["secret_ref"] = connection.get("secret_ref")

            if "is_default" in connection and connection["is_default"] is not None:
                if not _is_bool(connection["is_default"]):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "is_default must be boolean", field="connection.is_default"), "VALIDATION_ERROR", acct=row.get("account_id"))
                row["is_default"] = bool(connection["is_default"])

            # enforce "at most one active default" if set to default & active
            if row.get("is_default") is True and row.get("status") == "active":
                for c in conns:
                    if c.get("id") != row.get("id") and c.get("account_id") == row.get("account_id") and c.get("status") == "active" and c.get("is_default") is True:
                        c["is_default"] = False
                        c["updated_at"] = now_iso

            # enforce is_default implies active
            if row.get("is_default") is True and row.get("status") != "active":
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "is_default implies status='active'", constraint="is_default implies status='active'"), "VALIDATION_ERROR", acct=row.get("account_id"))

            row["updated_at"] = now_iso
            _save("databricks_connections.json", conns)
            return _log_and_return(fn, logs, {"connection": row}, "OK", acct=row.get("account_id"))

        if action == "delete_connection":
            cid = connection_id
            if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection_id is required", field="connection_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            row = _conn_by_id(cid)
            if row is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=cid), "NOT_FOUND", acct=ctx_account.get("id"))

            acct = _account_by_id(row.get("account_id"))
            e = _deny_if_account_inactive_for_mutations(acct)
            if e:
                return _log_and_return(fn, logs, e, "UNAUTHORIZED", acct=row.get("account_id"))

            if row.get("status") == "deleted":
                return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Connection is already deleted."), "INVALID_TRANSITION", acct=row.get("account_id"))

            # soft delete transition active/disabled -> deleted
            if row.get("status") not in ("active", "disabled"):
                return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Illegal connection status transition.", from_status=row.get("status"), to_status="deleted"), "INVALID_TRANSITION", acct=row.get("account_id"))

            row["status"] = "deleted"
            row["is_default"] = False
            row["updated_at"] = now_iso
            _save("databricks_connections.json", conns)
            return _log_and_return(fn, logs, {"connection": row}, "OK", acct=row.get("account_id"))

        if action == "set_default_connection":
            payload = set_default if _is_obj(set_default) else {}
            aid = payload.get("account_id") or account_id or ctx_account.get("id")
            cid = payload.get("connection_id") or connection_id
            if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", aid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "account_id is required", field="account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection_id is required", field="connection_id"), "VALIDATION_ERROR", acct=aid)

            acct = _account_by_id(aid)
            e = _deny_if_account_inactive_for_mutations(acct)
            if e:
                return _log_and_return(fn, logs, e, "UNAUTHORIZED", acct=aid)

            row = _conn_by_id(cid)
            if row is None or row.get("account_id") != aid:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found for account.", connection_id=cid, account_id=aid), "NOT_FOUND", acct=aid)

            if row.get("status") != "active":
                return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Only active connections can be default.", rule="default requires active connection"), "INVALID_TRANSITION", acct=aid)

            # unset all other active defaults, set this
            changed = False
            for c in conns:
                if c.get("account_id") == aid and c.get("status") == "active":
                    if c.get("id") == cid:
                        if c.get("is_default") is not True:
                            c["is_default"] = True
                            c["updated_at"] = now_iso
                            changed = True
                    else:
                        if c.get("is_default") is True:
                            c["is_default"] = False
                            c["updated_at"] = now_iso
                            changed = True
            if not changed:
                # already default => idempotent but still effect? if none changed, treat as success with current resource
                return _log_and_return(fn, logs, {"connection": row}, "OK", acct=aid, meta={"idempotent": True})
            _save("databricks_connections.json", conns)
            # refresh row pointer
            row = _conn_by_id(cid)
            return _log_and_return(fn, logs, {"connection": row}, "OK", acct=aid)

        if action == "validate_connection":
            cid = connection_id
            if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection_id is required", field="connection_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            row = _conn_by_id(cid)
            if row is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=cid), "NOT_FOUND", acct=ctx_account.get("id"))
            if row.get("status") != "active":
                return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Cannot validate a non-active connection.", rule="validate requires active connection"), "INVALID_TRANSITION", acct=row.get("account_id"))
            # No real Databricks calls offline; mark validated
            row["last_validated_at"] = now_iso
            row["updated_at"] = now_iso
            _save("databricks_connections.json", conns)
            return _log_and_return(fn, logs, {"connection": row, "validated": True}, "OK", acct=row.get("account_id"))

        # --- api keys ---
        if action == "list_api_keys":
            filt = api_keys_filter if _is_obj(api_keys_filter) else {}
            rows = keys[:]
            acct_filter = filt.get("account_id") or account_id or ctx_account.get("id")
            if acct_filter is not None:
                if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", acct_filter):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid api_keys_filter.account_id", field="api_keys_filter.account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
                rows = [r for r in rows if r.get("account_id") == acct_filter]
            if "connection_id" in filt and filt["connection_id"] is not None:
                if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", filt["connection_id"]):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid api_keys_filter.connection_id", field="api_keys_filter.connection_id"), "VALIDATION_ERROR", acct=acct_filter)
                rows = [r for r in rows if r.get("connection_id") == filt["connection_id"]]
            if "status" in filt and filt["status"] is not None:
                rows = [r for r in rows if r.get("status") == filt["status"]]
            if "scope" in filt and filt["scope"] is not None:
                rows = [r for r in rows if isinstance(r.get("scopes"), list) and filt["scope"] in r.get("scopes")]

            rows = _sort_rows(rows, sort_by or "created_at", sort_order or "desc")
            page, pe = _page(rows)
            if pe:
                return _log_and_return(fn, logs, pe, "VALIDATION_ERROR", acct=ctx_account.get("id"))
            return _log_and_return(fn, logs, page, "OK", acct=acct_filter)

        if action == "create_api_key":
            payload = create_api_key if _is_obj(create_api_key) else {}
            aid = payload.get("account_id") or account_id or ctx_account.get("id")
            nm = payload.get("name")
            scopes = payload.get("scopes")
            cid = payload.get("connection_id")
            exp_s = payload.get("expires_at")

            if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", aid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "account_id is required", field="account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            if not isinstance(nm, str) or not nm.strip():
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "name is required", field="name"), "VALIDATION_ERROR", acct=aid)
            if not isinstance(scopes, list) or len(scopes) < 1:
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "scopes must be a non-empty array", field="scopes"), "VALIDATION_ERROR", acct=aid)
            allowed_scopes = {"connections:read", "connections:write", "sessions:read", "sessions:write", "admin"}
            if any((not isinstance(s, str) or s not in allowed_scopes) for s in scopes):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid scopes value", allowed=sorted(allowed_scopes)), "VALIDATION_ERROR", acct=aid)

            acct = _account_by_id(aid)
            e = _deny_if_account_inactive_for_mutations(acct)
            if e:
                return _log_and_return(fn, logs, e, "UNAUTHORIZED", acct=aid)

            if cid is not None:
                if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid connection_id", field="connection_id"), "VALIDATION_ERROR", acct=aid)
                conn = _conn_by_id(cid)
                if conn is None:
                    return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=cid), "NOT_FOUND", acct=aid)
                if conn.get("account_id") != aid:
                    return _log_and_return(fn, logs, _err("UNAUTHORIZED", "connection_id does not belong to account."), "UNAUTHORIZED", acct=aid)

            # unique(account_id, name)
            for k in keys:
                if k.get("account_id") == aid and k.get("name") == nm:
                    return _log_and_return(fn, logs, _err("CONFLICT", "An API key with this name already exists for the account.", constraint="unique(account_id,name)"), "CONFLICT", acct=aid)

            exp_dt = None
            if exp_s is not None:
                exp_dt = _parse_dt(exp_s)
                if exp_dt is None:
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "expires_at must be RFC3339 datetime", field="expires_at"), "VALIDATION_ERROR", acct=aid)
                if exp_dt <= now:
                    # allow but key would be immediately expired in a real system; refuse active creation with past expiry
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "expires_at must be in the future", field="expires_at"), "VALIDATION_ERROR", acct=aid)

            # generate key material once
            key_plain = "dbmcp_key_" + secrets.token_urlsafe(24)
            key_prefix = key_plain[:10]
            # store plaintext in key_hash column for matching in this sandbox
            row = {
                "id": _gen_id("dbmcp_key"),
                "account_id": aid,
                "connection_id": cid,
                "name": nm,
                "key_prefix": key_prefix,
                "key_hash": key_plain,
                "scopes": scopes,
                "last_used_at": None,
                "expires_at": _iso_or_none(exp_dt) if exp_dt else None,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            keys.append(row)
            _save("api_keys.json", keys)
            return _log_and_return(fn, logs, {"api_key": row, "api_key_value": key_plain}, "OK", acct=aid)

        if action == "revoke_api_key":
            payload = revoke_api_key if _is_obj(revoke_api_key) else {}
            kid = payload.get("api_key_id") or api_key_id
            if not _match(r"^dbmcp_key_[0-9A-Z]{18,}$", kid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "api_key_id is required", field="api_key_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))

            row = _key_by_id(kid)
            if row is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "API key not found.", api_key_id=kid), "NOT_FOUND", acct=ctx_account.get("id"))

            acct = _account_by_id(row.get("account_id"))
            e = _deny_if_account_inactive_for_mutations(acct)
            if e:
                return _log_and_return(fn, logs, e, "UNAUTHORIZED", acct=row.get("account_id"))

            if row.get("status") == "revoked":
                return _log_and_return(fn, logs, {"api_key": row}, "OK", acct=row.get("account_id"), meta={"idempotent": True})

            # active -> revoked transition
            row["status"] = "revoked"
            row["updated_at"] = now_iso
            _save("api_keys.json", keys)
            return _log_and_return(fn, logs, {"api_key": row}, "OK", acct=row.get("account_id"))

        # --- accounts ---
        if action == "list_accounts":
            filt = accounts_filter if _is_obj(accounts_filter) else {}
            rows = accounts[:]
            if "status" in filt and filt["status"] is not None:
                rows = [r for r in rows if r.get("status") == filt["status"]]
            if "role" in filt and filt["role"] is not None:
                rows = [r for r in rows if r.get("role") == filt["role"]]
            if "email" in filt and filt["email"] is not None:
                if not isinstance(filt["email"], str) or not filt["email"]:
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "accounts_filter.email must be a string", field="accounts_filter.email"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
                rows = [r for r in rows if r.get("email") == filt["email"]]

            rows = _sort_rows(rows, sort_by or "created_at", sort_order or "desc")
            page, pe = _page(rows)
            if pe:
                return _log_and_return(fn, logs, pe, "VALIDATION_ERROR", acct=ctx_account.get("id"))
            return _log_and_return(fn, logs, page, "OK", acct=ctx_account.get("id"))

        if action == "get_account":
            aid = account_id or ctx_account.get("id")
            if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", aid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "account_id is required", field="account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            acct = _account_by_id(aid)
            if acct is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Account not found.", account_id=aid), "NOT_FOUND", acct=ctx_account.get("id"))
            return _log_and_return(fn, logs, {"account": acct}, "OK", acct=aid)

        if action == "update_account_status":
            if not _is_obj(update_account):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "update_account object is required", field="update_account"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
            aid = update_account.get("account_id") or account_id
            if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", aid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "update_account.account_id is required", field="update_account.account_id"), "VALIDATION_ERROR", acct=ctx_account.get("id"))

            acct = _account_by_id(aid)
            if acct is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Account not found.", account_id=aid), "NOT_FOUND", acct=ctx_account.get("id"))

            # transitions per schema
            transitions = {"active": {"suspended", "deleted"}, "suspended": {"active", "deleted"}, "deleted": set()}
            if "status" in update_account and update_account["status"] is not None:
                new_st = update_account["status"]
                if new_st not in ("active", "suspended", "deleted"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid status", field="update_account.status"), "VALIDATION_ERROR", acct=aid)
                old_st = acct.get("status")
                if new_st != old_st and new_st not in transitions.get(old_st, set()):
                    return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Illegal account status transition.", from_status=old_st, to_status=new_st), "INVALID_TRANSITION", acct=aid)
                acct["status"] = new_st

            if "role" in update_account and update_account["role"] is not None:
                if update_account["role"] not in ("owner", "admin", "member", "viewer"):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid role", field="update_account.role"), "VALIDATION_ERROR", acct=aid)
                acct["role"] = update_account["role"]

            if "display_name" in update_account:
                dn = update_account.get("display_name")
                if dn is not None and not isinstance(dn, str):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "display_name must be a string", field="update_account.display_name"), "VALIDATION_ERROR", acct=aid)
                acct["display_name"] = dn

            acct["updated_at"] = now_iso
            _save("accounts.json", accounts)
            return _log_and_return(fn, logs, {"account": acct}, "OK", acct=aid)

        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Unsupported action"), "VALIDATION_ERROR", acct=ctx_account.get("id"))
    except Exception as e:
        # unexpected programming/runtime issue should return error object, not raise
        return _log_and_return(fn, logs, _err("CONFLICT", "Server error while processing request.", detail=str(e)), "CONFLICT", acct=ctx_account.get("id"))

def Who_Am_I(session_token=None, api_key=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0073000" if __import__("os").path.isdir("./environment_mix/0073000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    ts = now.isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        # 20 chars base32-ish using os.urandom, uppercase letters+digits 2-7
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        raw = os.urandom(12)
        out = []
        for b in raw:
            out.append(alphabet[b & 31])
        return f"{prefix}_{''.join(out)}{alphabet[raw[0] & 31]}{alphabet[raw[1] & 31]}"

    def _log(status, credential_type=None, credential_id=None, account_id=None, meta=None):
        # Observable dynamics: create request log + enforce rate/quota based on it.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        duration_ms = int((time.time() - started) * 1000)
        row = {
            "id": _new_id("dbmcp_req"),
            "endpoint": "Who Am I",
            "timestamp": ts,
            "status": status,
            "latency_ms": duration_ms,
            "credential_type": credential_type,
            "credential_id": credential_id,
            "account_id": account_id,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Basic validation of parameters
    if session_token is not None and not isinstance(session_token, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "session_token must be a string")
    if api_key is not None and not isinstance(api_key, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string")
    if (session_token is None or session_token.strip() == "") and (api_key is None or api_key.strip() == ""):
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing credentials: provide session_token or api_key")

    accounts = _load("accounts.json")
    sessions = _load("auth_sessions.json")
    keys = _load("api_keys.json")
    if not isinstance(accounts, list): accounts = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(keys, list): keys = []

    # Apply lifecycle maintenance: mark active sessions expired if expires_at <= now
    changed_sessions = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                s["status"] = "expired"
                s["updated_at"] = ts
                changed_sessions = True
    if changed_sessions:
        _save("auth_sessions.json", sessions)

    def _find_account(acct_id):
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == acct_id:
                return a
        return None

    # Authenticate: match plaintext provided against stored hash field (per spec).
    authed = None
    # Prefer session_token if provided; else api_key. If both provided, accept whichever is valid.
    if session_token is not None and session_token.strip() != "":
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("session_token_hash") == session_token:
                authed = ("session", s)
                break

    if authed is None and api_key is not None and api_key.strip() != "":
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("key_hash") == api_key:
                authed = ("api_key", k)
                break

    if authed is None:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid credential")

    ctype, crow = authed
    account_id = crow.get("account_id")
    acct = _find_account(account_id)
    if acct is None:
        _log("UNAUTHORIZED", credential_type=ctype, credential_id=crow.get("id"), account_id=account_id)
        return _err("UNAUTHORIZED", "Credential is not associated with a valid account")

    # Credential-specific checks
    if ctype == "session":
        # status must be active, not revoked, not expired
        st = crow.get("status")
        exp = _parse_dt(crow.get("expires_at"))
        revoked_at = _parse_dt(crow.get("revoked_at"))
        if st == "revoked" or revoked_at is not None:
            _log("UNAUTHORIZED", credential_type="session", credential_id=crow.get("id"), account_id=account_id)
            return _err("UNAUTHORIZED", "Session is revoked")
        if st == "expired" or (exp is not None and exp <= now):
            # If it wasn't updated yet, update now
            if crow.get("status") != "expired":
                crow["status"] = "expired"
                crow["updated_at"] = ts
                _save("auth_sessions.json", sessions)
            _log("UNAUTHORIZED", credential_type="session", credential_id=crow.get("id"), account_id=account_id)
            return _err("UNAUTHORIZED", "Session is expired")
        if st != "active":
            _log("UNAUTHORIZED", credential_type="session", credential_id=crow.get("id"), account_id=account_id)
            return _err("UNAUTHORIZED", "Session is not active")

        # Sessions effectively have session scopes (read/write sessions, read connections) unless account role is admin/owner
        effective_scopes = ["sessions:read", "sessions:write", "connections:read"]
        if acct.get("role") in ("owner", "admin"):
            effective_scopes = sorted(set(effective_scopes + ["admin", "connections:write"]))
    else:
        st = crow.get("status")
        exp = _parse_dt(crow.get("expires_at"))
        if st != "active":
            _log("UNAUTHORIZED", credential_type="api_key", credential_id=crow.get("id"), account_id=account_id)
            return _err("UNAUTHORIZED", "API key is revoked or inactive")
        if exp is not None and exp <= now:
            # Enforce rule: expired keys must not be active; treat as unauthorized and mark revoked for observability
            crow["status"] = "revoked"
            crow["updated_at"] = ts
            _save("api_keys.json", keys)
            _log("UNAUTHORIZED", credential_type="api_key", credential_id=crow.get("id"), account_id=account_id)
            return _err("UNAUTHORIZED", "API key is expired")
        scopes = crow.get("scopes")
        if not isinstance(scopes, list):
            scopes = []
        effective_scopes = scopes[:]
        if acct.get("role") in ("owner", "admin") and "admin" not in effective_scopes:
            # role does not automatically grant admin beyond key scopes, but does confer elevated identity.
            pass

    # Update last_used_at / last_login_at
    if ctype == "api_key":
        crow["last_used_at"] = ts
        crow["updated_at"] = ts
        _save("api_keys.json", keys)
    else:
        acct["last_login_at"] = ts
        acct["updated_at"] = ts
        _save("accounts.json", accounts)

    # Rate/quota consumption (derived from request logs if present)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # For credential-based quotas, count last 60s and last 24h for this credential_id
    cred_id = crow.get("id")
    one_min_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)

    def _log_dt(row):
        return _parse_dt((row or {}).get("timestamp"))

    per_min = 0
    per_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential_id") != cred_id or r.get("credential_type") != ctype:
            continue
        dt = _log_dt(r)
        if dt is None:
            continue
        if dt >= one_min_ago:
            per_min += 1
        if dt >= day_ago:
            per_day += 1

    # Log this call as success
    _log("OK", credential_type=ctype, credential_id=cred_id, account_id=account_id)

    return {
        "identity": {
            "credential_type": ctype,
            "credential_id": cred_id,
            "account": {
                "id": acct.get("id"),
                "email": acct.get("email"),
                "display_name": acct.get("display_name"),
                "role": acct.get("role"),
                "status": acct.get("status")
            },
            "connection_id": crow.get("connection_id") if ctype == "session" else crow.get("connection_id")
        },
        "entitlements": {
            "effective_scopes": effective_scopes
        },
        "usage": {
            "requests_last_60s": per_min,
            "requests_last_24h": per_day
        }
    }

def Optional_Settings__auth_sessions_(action, session_token=None, api_key=None, account_id=None, session_id=None, connection_id=None, client_metadata=None, expires_in_seconds=None, limit=None, cursor=None, sort_by=None, sort_order=None, sessions_filter=None, **_extra):
    import json, os, datetime, time, re, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0073000" if __import__("os").path.isdir("./environment_mix/0073000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    endpoint = "Optional Settings (auth_sessions)"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _find_log_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _load_logs(fn):
        logs = _load(fn)
        return logs if isinstance(logs, list) else []

    def _enforce_limits(logs, limit_key):
        window_sec = 60
        rate_limit = 120
        daily_quota = 10000
        win_start = now - datetime.timedelta(seconds=window_sec)
        day_start = datetime.datetime(now.year, now.month, now.day)
        rate_count = 0
        day_count = 0
        for r in logs:
            if r.get("limit_key") != limit_key:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                rate_count += 1
            if ts >= day_start:
                day_count += 1
        if rate_count >= rate_limit:
            return _err("RATE_LIMIT", "Too many requests; slow down.", limit=rate_limit, window_seconds=window_sec)
        if day_count >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota=daily_quota, period="day")
        return None

    def _log_and_return(fn, logs, resp, status, credential_type=None, credential_id=None, acct=None, meta=None):
        logs.append({
            "id": _gen_id("dbmcp_req"),
            "endpoint": endpoint,
            "timestamp": now_iso,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_type": credential_type,
            "credential_id": credential_id,
            "account_id": acct,
            "limit_key": acct or credential_id or "anonymous",
            "meta": meta or {}
        })
        _save(fn, logs)
        return resp

    # validate action
    allowed = {"list_sessions", "get_session", "create_session", "revoke_session", "expire_session"}
    fn = _find_log_file()
    logs = _load_logs(fn)

    if not isinstance(action, str) or action not in allowed:
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid action", allowed=sorted(allowed)), "VALIDATION_ERROR")

    # load data
    accounts = _load("accounts.json");  accounts = accounts if isinstance(accounts, list) else []
    conns = _load("databricks_connections.json"); conns = conns if isinstance(conns, list) else []
    sessions = _load("auth_sessions.json"); sessions = sessions if isinstance(sessions, list) else []
    keys = _load("api_keys.json"); keys = keys if isinstance(keys, list) else []

    # auto-expire
    sessions_changed = False
    for s in sessions:
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now and s.get("revoked_at") is None:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                sessions_changed = True
    if sessions_changed:
        _save("auth_sessions.json", sessions)

    def _match(pat, s):
        return isinstance(s, str) and re.match(pat, s) is not None

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    # authenticate: match presented value against stored *hash field* value directly (no hashing)
    authed_account_id = None
    cred_type = None
    cred_id = None

    if isinstance(session_token, str) and session_token:
        for s in sessions:
            if s.get("session_token_hash") == session_token and s.get("status") == "active" and s.get("revoked_at") is None:
                exp = _parse_dt(s.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = s.get("account_id")
                    cred_type = "session_token"
                    cred_id = s.get("id")
                    break

    if authed_account_id is None and isinstance(api_key, str) and api_key:
        for k in keys:
            if k.get("key_hash") == api_key and k.get("status") == "active":
                exp = _parse_dt(k.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = k.get("account_id")
                    cred_type = "api_key"
                    cred_id = k.get("id")
                    # update last_used_at
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    _save("api_keys.json", keys)
                    break

    if authed_account_id is None:
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Authentication required: provide a valid session_token or api_key."), "UNAUTHORIZED")

    lim_err = _enforce_limits(logs, authed_account_id)
    if lim_err:
        return _log_and_return(fn, logs, lim_err, "RATE_LIMIT", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    def _account_by_id(aid):
        for a in accounts:
            if a.get("id") == aid:
                return a
        return None

    def _conn_by_id(cid):
        for c in conns:
            if c.get("id") == cid:
                return c
        return None

    def _sess_by_id(sid):
        for s in sessions:
            if s.get("id") == sid:
                return s
        return None

    caller_acct = _account_by_id(authed_account_id)
    if caller_acct is None or caller_acct.get("status") != "active":
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Authenticated account is not active."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        s = cur.strip()
        if s.isdigit():
            return int(s)
        try:
            pad = "=" * ((4 - len(s) % 4) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii")).decode("utf-8")
            return int(raw)
        except Exception:
            return None

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("ascii").rstrip("=")

    def _sort_rows(rows, by, order):
        reverse = (order == "desc")
        if not by:
            return rows
        def keyfn(r):
            v = r.get(by)
            dt = _parse_dt(v) if by in ("created_at", "updated_at", "expires_at", "issued_at") else None
            return dt or ("" if v is None else v)
        return sorted(rows, key=keyfn, reverse=reverse)

    def _page(rows):
        lim = limit if limit is not None else 50
        start = _decode_cursor(cursor)
        if start is None:
            return None, _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        total = len(rows)
        end = min(start + lim, total)
        out = rows[start:end]
        has_more = end < total
        return {
            "data": out,
            "total": total,
            "limit": lim,
            "cursor": cursor,
            "next_cursor": _encode_cursor(end) if has_more else None,
            "has_more": has_more
        }, None

    # input validation
    if limit is not None and (not _is_int(limit) or limit < 1 or limit > 200):
        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    if sort_order is not None and sort_order not in ("asc", "desc"):
        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # ACTIONS
    try:
        if action == "list_sessions":
            filt = sessions_filter if isinstance(sessions_filter, dict) else {}
            rows = sessions[:]

            # default restrict to calling account unless a different account_id is requested (still require visibility)
            req_acct = filt.get("account_id") or account_id or authed_account_id
            if req_acct is not None:
                if not _match(r"^dbmcp_acct_[0-9A-Z]{18,}$", req_acct):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid account_id filter", field="account_id"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
                if req_acct != authed_account_id:
                    return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Cannot list sessions for a different account."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
                rows = [r for r in rows if r.get("account_id") == req_acct]

            if "connection_id" in filt and filt["connection_id"] is not None:
                if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", filt["connection_id"]):
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid connection_id filter", field="sessions_filter.connection_id"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
                rows = [r for r in rows if r.get("connection_id") == filt["connection_id"]]
            if "status" in filt and filt["status"] is not None:
                rows = [r for r in rows if r.get("status") == filt["status"]]

            rows = _sort_rows(rows, sort_by or "created_at", sort_order or "desc")
            page, pe = _page(rows)
            if pe:
                return _log_and_return(fn, logs, pe, "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            return _log_and_return(fn, logs, page, "OK", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

        if action == "get_session":
            sid = session_id
            if not _match(r"^dbmcp_sess_[0-9A-Z]{18,}$", sid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "session_id is required", field="session_id"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            s = _sess_by_id(sid)
            if s is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Session not found.", session_id=sid), "NOT_FOUND", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            if s.get("account_id") != authed_account_id:
                return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Session not visible to caller."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            return _log_and_return(fn, logs, {"session": s}, "OK", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

        if action == "create_session":
            # enforce suspended/deleted cannot create sessions
            if caller_acct.get("status") in ("suspended", "deleted"):
                return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Suspended/deleted accounts cannot create sessions."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

            aid = account_id or authed_account_id
            if aid != authed_account_id:
                return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Cannot create session for a different account."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

            cid = connection_id
            if not _match(r"^dbmcp_conn_[0-9A-Z]{18,}$", cid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "connection_id is required", field="connection_id"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

            conn = _conn_by_id(cid)
            if conn is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=cid), "NOT_FOUND", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            if conn.get("account_id") != authed_account_id:
                return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Connection not visible to caller."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            if conn.get("status") != "active":
                return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "New sessions may only target active connections.", rule="connection must be active"), "INVALID_TRANSITION", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

            if expires_in_seconds is not None:
                if not _is_int(expires_in_seconds) or expires_in_seconds < 300 or expires_in_seconds > 2592000:
                    return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "expires_in_seconds must be between 300 and 2592000", field="expires_in_seconds"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
                exp = now + datetime.timedelta(seconds=expires_in_seconds)
            else:
                exp = now + datetime.timedelta(hours=24)

            token_plain = "dbmcp_sess_tok_" + secrets.token_urlsafe(24)
            row = {
                "id": _gen_id("dbmcp_sess"),
                "account_id": authed_account_id,
                "connection_id": cid,
                "session_token_hash": token_plain,
                "issued_at": now_iso,
                "expires_at": exp.isoformat() + "Z",
                "revoked_at": None,
                "client_metadata": client_metadata if isinstance(client_metadata, dict) else (client_metadata if client_metadata is None else {"value": client_metadata}),
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            sessions.append(row)
            _save("auth_sessions.json", sessions)
            return _log_and_return(fn, logs, {"session": row, "session_token": token_plain}, "OK", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

        if action in ("revoke_session", "expire_session"):
            sid = session_id
            if not _match(r"^dbmcp_sess_[0-9A-Z]{18,}$", sid or ""):
                return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "session_id is required", field="session_id"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            s = _sess_by_id(sid)
            if s is None:
                return _log_and_return(fn, logs, _err("NOT_FOUND", "Session not found.", session_id=sid), "NOT_FOUND", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
            if s.get("account_id") != authed_account_id:
