                _save("auth_sessions.json", sessions)
                return _log_and_return(fn, logs, {"session": s}, "OK", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

            # expire_session
            if s.get("status") == "expired":
                return _log_and_return(fn, logs, {"session": s}, "OK", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id, meta={"idempotent": True})
