            # active -> expired
            s["status"] = "expired"
            # ensure expires_at <= now to satisfy constraints
            s["expires_at"] = now_iso
            s["updated_at"] = now_iso
            _save("auth_sessions.json", sessions)
            return _log_and_return(fn, logs, {"session": s}, "OK", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Unsupported action"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
    except Exception as e:
        return _log_and_return(fn, logs, _err("CONFLICT", "Server error while processing request.", detail=str(e)), "CONFLICT", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

def Optional_Settings__api_keys_(api_key_id, session_token=None, api_key=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0073000" if __import__("os").path.isdir("./environment_mix/0073000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    endpoint = "Optional Settings (api_keys)"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _find_log_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _load_logs(fn):
        logs = _load(fn)
        return logs if isinstance(logs, list) else []

    def _enforce_limits(logs, limit_key):
        window_sec = 60
        rate_limit = 120
        daily_quota = 10000
        win_start = now - datetime.timedelta(seconds=window_sec)
        day_start = datetime.datetime(now.year, now.month, now.day)
        rate_count = 0
        day_count = 0
        for r in logs:
            if r.get("limit_key") != limit_key:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                rate_count += 1
            if ts >= day_start:
                day_count += 1
        if rate_count >= rate_limit:
            return _err("RATE_LIMIT", "Too many requests; slow down.", limit=rate_limit, window_seconds=window_sec)
        if day_count >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota=daily_quota, period="day")
        return None

    def _log_and_return(fn, logs, resp, status, credential_type=None, credential_id=None, acct=None, meta=None):
        logs.append({
            "id": _gen_id("dbmcp_req"),
            "endpoint": endpoint,
            "timestamp": now_iso,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_type": credential_type,
            "credential_id": credential_id,
            "account_id": acct,
            "limit_key": acct or credential_id or "anonymous",
            "meta": meta or {}
        })
        _save(fn, logs)
        return resp

    # validate api_key_id
    if not (isinstance(api_key_id, str) and re.match(r"^dbmcp_key_[0-9A-Z]{18,}$", api_key_id)):
        fn = _find_log_file()
        logs = _load_logs(fn)
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid api_key_id", field="api_key_id"), "VALIDATION_ERROR")

    fn = _find_log_file()
    logs = _load_logs(fn)

    accounts = _load("accounts.json"); accounts = accounts if isinstance(accounts, list) else []
    sessions = _load("auth_sessions.json"); sessions = sessions if isinstance(sessions, list) else []
    keys = _load("api_keys.json"); keys = keys if isinstance(keys, list) else []

    # authenticate
    authed_account_id = None
    cred_type = None
    cred_id = None

    if isinstance(session_token, str) and session_token:
        for s in sessions:
            if s.get("session_token_hash") == session_token and s.get("status") == "active" and s.get("revoked_at") is None:
                exp = _parse_dt(s.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = s.get("account_id")
                    cred_type = "session_token"
                    cred_id = s.get("id")
                    break

    if authed_account_id is None and isinstance(api_key, str) and api_key:
        for k in keys:
            if k.get("key_hash") == api_key and k.get("status") == "active":
                exp = _parse_dt(k.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = k.get("account_id")
                    cred_type = "api_key"
                    cred_id = k.get("id")
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    _save("api_keys.json", keys)
                    break

    if authed_account_id is None:
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Authentication required: provide a valid session_token or api_key."), "UNAUTHORIZED")

    lim_err = _enforce_limits(logs, authed_account_id)
    if lim_err:
        return _log_and_return(fn, logs, lim_err, "RATE_LIMIT", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # find requested key
    target = None
    for k in keys:
        if k.get("id") == api_key_id:
            target = k
            break
    if target is None:
        return _log_and_return(fn, logs, _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id), "NOT_FOUND", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    if target.get("account_id") != authed_account_id:
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "API key is not visible to the calling account."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # never return raw key material (key_hash may be treated as secret material)
    safe = dict(target)
    if "key_hash" in safe:
        safe["key_hash"] = None

    return _log_and_return(fn, logs, {"api_key": safe}, "OK", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

def Optional_Settings__rotate_api_key_(api_key_id, session_token=None, api_key=None, name=None, scopes=None, expires_at=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0073000" if __import__("os").path.isdir("./environment_mix/0073000") else "/app/database")
