            if s.get("session_token_hash") == session_token and s.get("status") == "active" and s.get("revoked_at") is None:
                exp = _parse_dt(s.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = s.get("account_id")
                    cred_type = "session_token"
                    cred_id = s.get("id")
                    break

    if authed_account_id is None and isinstance(api_key, str) and api_key:
        for k in keys:
            if k.get("key_hash") == api_key and k.get("status") == "active":
                exp = _parse_dt(k.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = k.get("account_id")
                    cred_type = "api_key"
                    cred_id = k.get("id")
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    _save("api_keys.json", keys)
                    break

    if authed_account_id is None:
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Authentication required: provide a valid session_token or api_key."), "UNAUTHORIZED")

    lim_err = _enforce_limits(logs, authed_account_id)
    if lim_err:
        return _log_and_return(fn, logs, lim_err, "RATE_LIMIT", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    def _account_by_id(aid):
        for a in accounts:
            if a.get("id") == aid:
                return a
        return None

    # locate old key
    old = None
    for k in keys:
        if k.get("id") == api_key_id:
            old = k
            break
    if old is None:
        return _log_and_return(fn, logs, _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id), "NOT_FOUND", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    if old.get("account_id") != authed_account_id:
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "API key is not visible to the calling account."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    if old.get("status") == "revoked":
        return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Cannot rotate a revoked API key.", rule="old key must be active"), "INVALID_TRANSITION", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    acct = _account_by_id(authed_account_id)
    if acct is None or acct.get("status") in ("suspended", "deleted"):
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Suspended/deleted accounts cannot rotate API keys."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # determine new properties
    new_name = name if isinstance(name, str) and name.strip() else old.get("name")
    new_scopes = scopes if isinstance(scopes, list) and len(scopes) > 0 else old.get("scopes")

    allowed_scopes = {"connections:read", "connections:write", "sessions:read", "sessions:write", "admin"}
    if not isinstance(new_scopes, list) or len(new_scopes) < 1 or any((not isinstance(s, str) or s not in allowed_scopes) for s in new_scopes):
        return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "Invalid scopes", allowed=sorted(allowed_scopes), field="scopes"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    exp_dt = None
    if expires_at is not None:
        exp_dt = _parse_dt(expires_at)
        if exp_dt is None:
            return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "expires_at must be RFC3339 datetime", field="expires_at"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)
        if exp_dt <= now:
            return _log_and_return(fn, logs, _err("VALIDATION_ERROR", "expires_at must be in the future", field="expires_at"), "VALIDATION_ERROR", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # unique(account_id, name) - allow same name if old is being revoked in same transaction (still conflict if another active/revoked exists with same name)
    for k in keys:
        if k.get("id") != old.get("id") and k.get("account_id") == authed_account_id and k.get("name") == new_name:
            return _log_and_return(fn, logs, _err("CONFLICT", "An API key with this name already exists for the account.", constraint="unique(account_id,name)"), "CONFLICT", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # rotate: create new row + revoke old row
    new_plain = "dbmcp_key_" + secrets.token_urlsafe(24)
    new_row = {
        "id": _gen_id("dbmcp_key"),
        "account_id": old.get("account_id"),
        "connection_id": old.get("connection_id"),
        "name": new_name,
        "key_prefix": new_plain[:10],
        "key_hash": new_plain,
        "scopes": new_scopes,
        "last_used_at": None,
        "expires_at": (exp_dt.replace(microsecond=0).isoformat() + "Z") if exp_dt else old.get("expires_at"),
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso
    }

    old["status"] = "revoked"
    old["updated_at"] = now_iso

    keys.append(new_row)
    _save("api_keys.json", keys)

    safe_new = dict(new_row)
    safe_new["key_hash"] = None
    safe_old = dict(old)
    safe_old["key_hash"] = None

    return _log_and_return(
        fn, logs,
        {"old_api_key": safe_old, "new_api_key": safe_new, "new_api_key_value": new_plain},
        "OK",
        credential_type=cred_type, credential_id=cred_id, acct=authed_account_id
    )

