    if isinstance(session_token, str) and session_token:
        for s in sessions:
            if s.get("session_token_hash") == session_token and s.get("status") == "active" and s.get("revoked_at") is None:
                exp = _parse_dt(s.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = s.get("account_id")
                    cred_type = "session_token"
                    cred_id = s.get("id")
                    break

    if authed_account_id is None and isinstance(api_key, str) and api_key:
        for k in keys:
            if k.get("key_hash") == api_key and k.get("status") == "active":
                exp = _parse_dt(k.get("expires_at"))
                if exp is None or exp > now:
                    authed_account_id = k.get("account_id")
                    cred_type = "api_key"
                    cred_id = k.get("id")
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    _save("api_keys.json", keys)
                    break

    if authed_account_id is None:
        lim_err = _enforce_limits(logs, "anonymous")
        if lim_err:
            return _log_and_return(fn, logs, lim_err, "RATE_LIMIT")
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Authentication required: provide a valid session_token or api_key."), "UNAUTHORIZED")

    lim_err = _enforce_limits(logs, authed_account_id)
    if lim_err:
        return _log_and_return(fn, logs, lim_err, "RATE_LIMIT", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # find connection
    conn = None
    for c in conns:
        if c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        return _log_and_return(fn, logs, _err("NOT_FOUND", "Connection not found.", connection_id=connection_id), "NOT_FOUND", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    if conn.get("account_id") != authed_account_id:
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Connection not visible to caller."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    if conn.get("status") == "deleted":
        return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Connection already deleted."), "INVALID_TRANSITION", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # enforce account status: suspended/deleted cannot update connections
    acct = None
    for a in accounts:
        if a.get("id") == authed_account_id:
            acct = a
            break
    if acct is None or acct.get("status") in ("suspended", "deleted"):
        return _log_and_return(fn, logs, _err("UNAUTHORIZED", "Suspended/deleted accounts cannot delete/update connections."), "UNAUTHORIZED", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    # maintenance operation: soft-delete and fix referencing sessions
    affected_sessions = []
    sessions_changed = False
    for s in sessions:
        if s.get("connection_id") == connection_id:
            if on_referenced_sessions == "revoke":
                if s.get("status") != "revoked":
                    # legal transitions: active->revoked, expired->revoked
                    if s.get("status") in ("active", "expired"):
                        s["status"] = "revoked"
                        s["revoked_at"] = now_iso
                        s["updated_at"] = now_iso
                        sessions_changed = True
                        affected_sessions.append(s.get("id"))
            else:
                # nullify_connection
                if s.get("connection_id") is not None:
                    s["connection_id"] = None
                    s["updated_at"] = now_iso
                    sessions_changed = True
                    affected_sessions.append(s.get("id"))

    # soft delete connection (active/disabled -> deleted)
    if conn.get("status") not in ("active", "disabled"):
        return _log_and_return(fn, logs, _err("INVALID_TRANSITION", "Illegal connection status transition.", from_status=conn.get("status"), to_status="deleted"), "INVALID_TRANSITION", credential_type=cred_type, credential_id=cred_id, acct=authed_account_id)

    conn["status"] = "deleted"
    conn["is_default"] = False
    conn["updated_at"] = now_iso

    _save("databricks_connections.json", conns)
    if sessions_changed:
        _save("auth_sessions.json", sessions)

    return _log_and_return(
        fn, logs,
        {"connection": conn, "referenced_sessions_affected": affected_sessions, "on_referenced_sessions": on_referenced_sessions},
        "OK",
        credential_type=cred_type, credential_id=cred_id, acct=authed_account_id
    )
